TESTDATA["pet5-t4"] = {"title": "Cambridge PET 5 · Test 4", "format": "2010", "reading": [{"part": 1, "items": [{"n": 1, "text": "To be taken between meals at six-hourly intervals, up to three times daily.", "img": "data:image/jpeg;base64,", "q": "It is essential", "options": ["to wait six hours before having more of this medicine.", "to take this medicine straight after meals.", "to use this medicine more than three times a day."], "answer": "A"}, {"n": 2, "text": "Louise,\nSuzie rang. The photo shop has lost all her photos of your trip to Vienna and she'd like copies of yours.\nMum", "img": "data:image/jpeg;base64,", "q": "What should Louise do?", "options": ["take some new photos of Suzie", "give Suzie some photos", "help Suzie find her photos"], "answer": "B"}, {"n": 3, "text": "Basketball Training\nProfessional coach available for pre-booked groups – 48 hours' notice required", "img": "data:image/jpeg;base64,", "q": "", "options": ["Basketball players are only allowed to practise here if accompanied by a professional coach.", "Basketball training for groups is cancelled until further notice.", "A basketball coach is available if a booking is made far enough in advance."], "answer": "C"}, {"n": 4, "text": "We're staying at the Plaza Hotel. It's not the hotel we wanted but it doesn't matter because this one is nearer the beach and I'm spending all my time there. Sabrina", "img": "data:image/jpeg;base64,", "q": "How does Sabrina feel about the Plaza Hotel?", "options": ["She's disappointed with it.", "She wishes it was nearer the beach.", "She thinks it has an advantage."], "answer": "C"}, {"n": 5, "text": "CHARLTON THEATRE\nBook early for Swan Lake to avoid disappointment as this is a popular show.", "img": "data:image/jpeg;base64,", "q": "", "options": ["We regret that there are no tickets left for the early performance of Swan Lake.", "If you want to see Swan Lake, buy your tickets as soon as possible.", "Swan Lake is unfortunately cancelled due to disappointing ticket sales."], "answer": "B"}]}, {"part": 2, "people": [{"n": 6, "name": "David", "text": "David enjoys spending time in the countryside, exploring different locations and learning about their past. He would enjoy listening to a description of somewhere that he could visit afterwards.", "answer": "C"}, {"n": 7, "name": "Emile", "text": "Emile enjoys classical music and drama and is interested in history. He would like to listen to a serious CD that will give information about a particular period of history.", "answer": "B"}, {"n": 8, "name": "Ysabelle", "text": "Ysabelle has to drive a lot for her job. She is looking for some amusing fiction to listen to in the car and would like a story that lasts a long time.", "answer": "F"}, {"n": 9, "name": "Omah", "text": "Omah is studying literature at university. He is particularly interested in modern poetry and would like to hear some of the poems he knows well being read aloud.", "answer": "E"}, {"n": 10, "name": "Tamsin", "text": "Tamsin's favourite novels take place in the past, and she likes exciting stories that move fast. She would like a CD that's easy to listen to and doesn't last too long.", "answer": "G"}], "texts": [{"letter": "A", "title": "Hafiz", "text": "Hafiz was a 14th-century Persian poet, and on this audiobook his poems are read aloud to a background of instrumental music. Natrakia Kallio reads beautifully. This CD is a great introduction to the work of Hafiz."}, {"letter": "B", "title": "Skulls and Skeletons", "text": "This recording about life in the 11th century was originally a radio series. In addition to the main text, some well-known musicians play instruments from the period, and some important documents and poetry of the time are read by actors."}, {"letter": "C", "title": "Coming Home", "text": "Jane Brown decided to take a look at a house for sale near where she grew up. The beauty of the house and the scenery around it amazed her. In this audiobook, she talks about local castles and ruins and gives lots of historical information about the area."}, {"letter": "D", "title": "The Apple Tree", "text": "The Lintons' house has no water or electricity but the beautiful countryside offers them peace and quiet. But when the Dobsons move in next door, things go frighteningly wrong. If you like mystery and suspense, and have plenty of time to listen, this is the novel for you."}, {"letter": "E", "title": "Off the Page", "text": "Listening to poems is one of our most ancient traditions and many people still believe that it's as important to listen to them as it is to read them. Here you can listen to some of the best poems from the 1980s to the present day. This is a great audiobook if you are short of time, as nothing in this collection lasts very long."}, {"letter": "F", "title": "Unlucky", "text": "When Mary Moreton throws herself into the back of George Bennet's taxi, he falls instantly in love with her. However, she is already in love with someone else. Events move quickly after that and the novel is very funny. You'll need several hours for this audiobook but it's great to listen to while you are busy with other jobs."}, {"letter": "G", "title": "Over the Horizon", "text": "Tim falls in love at first sight with Lily when he meets her on an 18th-century prison ship. The ship sinks, he rescues her, and they run away together. The action builds throughout the story. Listeners who enjoy historical adventure will love this book. This is not serious fiction though, and it's all over pretty quickly."}, {"letter": "H", "title": "Mother Learns to Drive", "text": "This is an amusing collection of true stories about growing up in the American countryside. In one particularly funny story, the author describes his mother learning to drive. This is a fairly long audiobook, but it is easy to listen to."}]}, {"part": 3, "title": "Free-diving in the Caribbean", "text": "Tanya Streeter holds four world records in free-diving, the sport in which competitors reach extraordinary depths on only one breath of air.\n\nIn 2003, Tanya Streeter made history when she became the first person to dive 120 metres into the ocean while holding her breath, and come back up to the top without help. She had been deeper a year before but on that occasion she swam back up using a balloon. This time, however, she held her breath for over three and a half minutes, which made her the only female in any sport to break the world record of a man. A team of fourteen safety divers at different depths watched the dive.\n\nFollowing reports of several serious accidents involving other divers, some people have complained that free-diving is too dangerous a sport, but Tanya doesn't agree, insisting that safety is the most important thing, followed closely by training.\n\nMost free-divers concentrate on one or two types of event within the sport, but whatever Tanya is in training for, her practice timetable remains the same. Two thirds of the programme is spent doing land-based training at the gym, with the rest divided between the pool and the ocean. She uses an exercise bike to help improve the fitness of her heart. However, she doesn't run, whether outdoors or on running machines, because she doesn't want to injure her knees. Instead, she finds that fast walking is a very good way to build her fitness. When she starts doing practice dives, she generally travels away from home. She aims to do fourteen dives over a four-week period, with a rest day between each diving day. It is essential that she doesn't get tired because that could ruin all the preparation.\n\nWhen Tanya is not preparing for an event, she makes frequent public appearances, mainly to advertise sports products. She has also supported environmental organisations, for example doing research projects or making films. Spending her childhood on the Caribbean island of Grand Cayman, she went swimming whenever she could, and long afternoons were spent exploring rock pools in order to watch the sea life. Tanya says that her life today is like living her childhood dreams. Because she is well-known in some countries, she thinks people are prepared to listen to her when she is talking about environmental issues.\n\nAs for the future, Tanya, who is now in her thirties, says she plans to keep breaking her own world records. As she didn't take up free-diving until she was twenty-five, Tanya is keen to stress that she doesn't intend to retire from the sport for many years to come.", "items": [{"n": 11, "q": "Tanya Streeter's world record in 2003 was the deepest she had ever dived.", "answer": "B"}, {"n": 12, "q": "There were other people in the water with Tanya during her record-breaking dive.", "answer": "A"}, {"n": 13, "q": "Tanya accepts that free-diving can be an extremely dangerous activity.", "answer": "B"}, {"n": 14, "q": "Tanya's training programme depends on the event she is preparing for.", "answer": "B"}, {"n": 15, "q": "Most of Tanya's training takes place in the water.", "answer": "B"}, {"n": 16, "q": "Tanya is careful to limit the number of training dives she does in a month.", "answer": "A"}, {"n": 17, "q": "Tanya spends more time helping environmental organisations than appearing in advertisements.", "answer": "B"}, {"n": 18, "q": "Tanya's interest in the natural world started at an early age.", "answer": "A"}, {"n": 19, "q": "Tanya has found that being famous has its advantages.", "answer": "A"}, {"n": 20, "q": "Because she started free-diving fairly late, Tanya feels her sports career may be short.", "answer": "B"}]}, {"part": 4, "title": "Little Chefs", "text": "For one group of children aged between ten and fifteen, Saturdays are spent learning the art of serious cooking. Their weekly lessons in small classes are so popular that there is a waiting list of 30 children who want to do the course. Parents pay £280 for the course where their children can have fun and learn how to make good food.\n\nClass member Bill, aged ten, says, 'I love my mum's cooking and now I can do it better than her. The teachers make us laugh, especially when we sit down with them to share the food we've made.'\n\nFlora is twelve, and she's having problems preparing onions. 'I love cooking. I did a meal for ten friends which they really enjoyed. Then my mum suggested I take up a hobby, instead of doing nothing at weekends. I was happy staying at home, so I wasn't too keen at first. I'm really glad I decided to come, though.'\n\nTheir teacher, Philippe, says, 'It's great fun. Children pay attention and remember things better than adults, although the kitchen isn't always as tidy when they're cooking! As adults, we're always learning more about food. If parents interest their children in cooking while they are young, they'll have enough skill to make food for themselves when they leave home.'", "items": [{"n": 21, "q": "What is the writer trying to do in the text?", "options": ["warn parents not to expect too much from their children", "advertise schools that teach people how to cook", "describe how some children spend their spare time", "explain why parents want to learn more about cooking"], "answer": "C"}, {"n": 22, "q": "What can a reader find out from the text?", "options": ["which dishes students prefer to cook on the course", "why the classes are so successful", "how much one lesson costs", "when the next classes begin"], "answer": "B"}, {"n": 23, "q": "Why did Flora join the course?", "options": ["Her friends persuaded her to do it.", "She wanted to learn to cook a big meal.", "She felt bored at weekends, with nothing to do.", "Her mother wanted her to develop an interest."], "answer": "D"}, {"n": 24, "q": "What does Philippe say about his young students?", "options": ["They will be confident about cooking in the future.", "They have a good memory but don't always listen.", "They keep the kitchen cleaner than adults do.", "They teach their parents what they have learnt in class."], "answer": "A"}, {"n": 25, "q": "What would one of Philippe's students say to a friend?", "options": ["We made onion soup yesterday. The course is great, although there are 30 people in my class.", "I go every Saturday, and now I can cook as well as my mum. I'm ten, and I'm the oldest.", "It's great. No one's over 15 and the food looks delicious. I just wish we could eat it together instead of taking it home.", "I was on a waiting list for ages, but now I'm on the course. Last week I cut up some onions – it was hard!"], "answer": "D"}]}, {"part": 5, "title": "San Francisco", "text": "San Francisco lies (0) ……… (on) the coast of northern California. The earliest Europeans to discover the [26] were led by a Spanish explorer [27] name was Gaspar de Portolá.\nHe first saw it in 1769. Surprisingly, [28] San Francisco Bay is a wonderful natural harbour, it was discovered by land [29] than by sea.\nIn 1849, people [30] in San Francisco in their thousands [31] to find gold. However, it was not the men looking for the gold that got rich. The richest people [32] their money from owning banks and law firms and they built themselves large houses on one of the hills. This was [33] as Nob Hill.\nNowadays, tourists are [34] to San Francisco because there they can see famous places like Chinatown and the Golden Gate Bridge. Many even [35] the short boat trip to the island of Alcatraz to see the former prison.", "gaps": {"26": {"options": ["area", "part", "space", "position"], "answer": "A"}, "27": {"options": ["who", "whose", "what", "which"], "answer": "B"}, "28": {"options": ["if", "unless", "although", "despite"], "answer": "C"}, "29": {"options": ["except", "instead", "apart", "rather"], "answer": "D"}, "30": {"options": ["reached", "arrived", "entered", "approached"], "answer": "B"}, "31": {"options": ["wondering", "hoping", "considering", "depending"], "answer": "B"}, "32": {"options": ["did", "became", "made", "brought"], "answer": "C"}, "33": {"options": ["told", "called", "named", "known"], "answer": "D"}, "34": {"options": ["interested", "attracted", "pleased", "excited"], "answer": "B"}, "35": {"options": ["take", "spend", "go", "travel"], "answer": "A"}}}], "writing": [{"part": 1, "title": "Here are some sentences about a camping holiday.", "items": [{"n": 1, "first": "The campsite was not far from the sea.", "before": "The campsite was quite", "after": "the sea.", "answers": ["near to", "close to"]}, {"n": 2, "first": "Sebastian asked the manager where the showers were.", "before": "Sebastian asked the manager, 'Where", "after": "showers?'", "answers": ["are the"]}, {"n": 3, "first": "Sebastian succeeded in putting up the tent on his own.", "before": "Sebastian was able", "after": "up the tent on his own.", "answers": ["to put"]}, {"n": 4, "first": "Sebastian and his friends went swimming every day.", "before": "Every day Sebastian went swimming and", "after": "did his friends.", "answers": ["so"]}, {"n": 5, "first": "The sea was warmer than they had expected.", "before": "The sea was not as", "after": "they had expected.", "answers": ["cold as"]}]}, {"part": 2, "items": [{"n": 6, "kind": "message", "task": "You are going to miss your English class tomorrow.\n\nWrite a note to your English teacher. In your note, you should\n• apologise for missing tomorrow's class\n• explain why you can't be there\n• suggest what you could do to cover the work you miss.\n\nWrite 35–45 words on your answer sheet.", "points": ["scusarti perché domani mancherai alla lezione di inglese", "spiegare perché non puoi venire", "suggerire che cosa puoi fare per recuperare il lavoro"]}]}, {"part": 3, "items": [{"n": 7, "kind": "letter", "task": "This is part of a letter you receive from an English penfriend.\n\n'I've just bought some new trousers. They're black and I really like them. Tell me about the clothes you like wearing. Do you enjoy shopping for clothes?'\n\nNow write a letter to your penfriend about clothes.\nWrite your letter in about 100 words on your answer sheet."}, {"n": 8, "kind": "story", "task": "Your English teacher has asked you to write a story.\nThis is the title for your story:\n\nThe lost suitcase\n\nWrite your story in about 100 words on your answer sheet."}]}], "listening": [{"part": 1, "audio": "audio/pet5-t4-l1.mp3", "items": [{"n": 1, "q": "Which of Miranda's things will Lucy be able to use?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}, {"n": 2, "q": "What can't the woman find?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 3, "q": "Which ring has the woman lost?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}, {"n": 4, "q": "What time did the girl arrive?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}, {"n": 5, "q": "What will be on television at 10 o'clock this evening?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 6, "q": "Where will the party be?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 7, "q": "What did the man buy?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}]}, {"part": 2, "intro": "You will hear a man called Paul Hart talking about his trip to Africa with a team of scientists.", "audio": "audio/pet5-t4-l2.mp3", "items": [{"n": 8, "q": "Why did Paul choose the part of Africa he visited?", "options": ["It is good for walking.", "It will soon change.", "He had been there before."], "answer": "B"}, {"n": 9, "q": "What made the team's journey slow?", "options": ["clearing paths through the forest", "finding somewhere safe to camp", "carrying heavy equipment"], "answer": "A"}, {"n": 10, "q": "What did Paul worry about during the trip?", "options": ["the number of dangerous animals", "getting the information he needed", "being responsible for a team of people"], "answer": "C"}, {"n": 11, "q": "Paul says that the team didn't have enough food because", "options": ["some people ate more than they should.", "the walk took longer than expected.", "some of the food went bad too quickly."], "answer": "A"}, {"n": 12, "q": "Why were the team grateful to a fisherman they met?", "options": ["He let everyone rest on his boat.", "He helped one of them who was ill.", "He told them which direction to take."], "answer": "B"}, {"n": 13, "q": "How does Paul feel now he is back home?", "options": ["He is planning to do another trip.", "He misses the people in the team.", "He thinks the trip was a valuable experience."], "answer": "C"}]}, {"part": 3, "intro": "You will hear a woman talking about flights in a hot air balloon.", "audio": "audio/pet5-t4-l3.mp3", "notes": "Hot Air Balloon Flights\nChildren under 12 must be with an adult.\nAll passengers need to be [14].\nBalloon flights are best when there are light winds, no [15] and a clear sky.\nPassengers need to wear outdoor clothes and [16].\nFlights travel between 5 and 30 kilometres.\nPassengers return to the airfield in a [17].\nFlights are available from the month of [18] each year.\nFor booking and information, phone [19] or visit www.hotairballoons.com", "answers": {"14": ["fit"], "15": ["rain"], "16": ["boots"], "17": ["mini-bus", "minibus", "mini bus", "mini-buses", "minibuses"], "18": ["March"], "19": ["01252 88492", "0125288492", "01252-88492"]}}, {"part": 4, "intro": "You will hear a conversation between a girl called Ella, and her father, about the school holidays.", "audio": "audio/pet5-t4-l4.mp3", "items": [{"n": 20, "q": "Ella and her father both think she has worked hard.", "answer": "A"}, {"n": 21, "q": "Ella is happy to be alone during the holidays.", "answer": "A"}, {"n": 22, "q": "Ella has a lot in common with her friends.", "answer": "B"}, {"n": 23, "q": "The family's last camping trip was unsuccessful.", "answer": "A"}, {"n": 24, "q": "Someone has asked Ella to look after a horse in the holidays.", "answer": "B"}, {"n": 25, "q": "Ella's father is keen for her to spend the holidays relaxing.", "answer": "B"}]}]};
